static const lxl_str sl6528 = {.p = sl6528b, .cap = 0U, .len = 55U};
static char sl6529b[57] = " * software is freely granted, provided that this notice";
static const lxl_str sl6529 = {.p = sl6529b, .cap = 0U, .len = 56U};
static char sl6530b[17] = " * is preserved.";
static const lxl_str sl6530 = {.p = sl6530b, .cap = 0U, .len = 16U};
static char sl6531b[12] = "/* expm1(x)";
static const lxl_str sl6531 = {.p = sl6531b, .cap = 0U, .len = 11U};
static char sl6532b[51] = " * Returns exp(x)-1, the exponential of x minus 1.";
static const lxl_str sl6532 = {.p = sl6532b, .cap = 0U, .len = 50U};
static char sl6533b[10] = " * Method";
static const lxl_str sl6533 = {.p = sl6533b, .cap = 0U, .len = 9U};
static char sl6534b[28] = " *   1. Argument reduction:";
static const lxl_str sl6534 = {.p = sl6534b, .cap = 0U, .len = 27U};
static char sl6535b[48] = " *      Given x, find r and integer k such that";
static const lxl_str sl6535 = {.p = sl6535b, .cap = 0U, .len = 47U};
static char sl6536b[58] = " *               x = k*ln2 + r,  |r| <= 0.5*ln2 ~ 0.34658";
static const lxl_str sl6536 = {.p = sl6536b, .cap = 0U, .len = 57U};
static char sl6537b[64] = " *      Here a correction term c will be computed to compensate";
static const lxl_str sl6537 = {.p = sl6537b, .cap = 0U, .len = 63U};
static char sl6538b[64] = " *      the error in r when rounded to a floating-point number.";
static const lxl_str sl6538 = {.p = sl6538b, .cap = 0U, .len = 63U};
static char sl6539b[65] = " *   2. Approximating expm1(r) by a special rational function on";
static const lxl_str sl6539 = {.p = sl6539b, .cap = 0U, .len = 64U};
static char sl6540b[34] = " *      the interval [0,0.34658]:";
static const lxl_str sl6540 = {.p = sl6540b, .cap = 0U, .len = 33U};
static char sl6541b[14] = " *      Since";
static const lxl_str sl6541 = {.p = sl6541b, .cap = 0U, .len = 13U};
static char sl6542b[63] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 - r^4/360 + ...";
static const lxl_str sl6542 = {.p = sl6542b, .cap = 0U, .len = 62U};
static char sl6543b[29] = " *      we define R1(r*r) by";
static const lxl_str sl6543 = {.p = sl6543b, .cap = 0U, .len = 28U};
static char sl6544b[57] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 * R1(r*r)";
static const lxl_str sl6544 = {.p = sl6544b, .cap = 0U, .len = 56U};
static char sl6545b[17] = " *      That is,";
static const lxl_str sl6545 = {.p = sl6545b, .cap = 0U, .len = 16U};
static char sl6546b[58] = " *          R1(r**2) = 6/r *((exp(r)+1)/(exp(r)-1) - 2/r)";
static const lxl_str sl6546 = {.p = sl6546b, .cap = 0U, .len = 57U};
static char sl6547b[61] = " *                   = 6/r * ( 1 + 2.0*(1/(exp(r)-1) - 1/r))";
static const lxl_str sl6547 = {.p = sl6547b, .cap = 0U, .len = 60U};
static char sl6548b[64] = " *                   = 1 - r^2/60 + r^4/2520 - r^6/100800 + ...";
static const lxl_str sl6548 = {.p = sl6548b, .cap = 0U, .len = 63U};
static char sl6549b[66] = " *      We use a special Remez algorithm on [0,0.347] to generate";
static const lxl_str sl6549 = {.p = sl6549b, .cap = 0U, .len = 65U};
static char sl6550b[63] = " *      a polynomial of degree 5 in r*r to approximate R1. The";
static const lxl_str sl6550 = {.p = sl6550b, .cap = 0U, .len = 62U};
static char sl6551b[66] = " *      maximum error of this polynomial approximation is bounded";
static const lxl_str sl6551 = {.p = sl6551b, .cap = 0U, .len = 65U};
static char sl6552b[35] = " *      by 2**-61. In other words,";
static const lxl_str sl6552 = {.p = sl6552b, .cap = 0U, .len = 34U};
static char sl6553b[71] = " *          R1(z) ~ 1.0 + Q1*z + Q2*z**2 + Q3*z**3 + Q4*z**4 + Q5*z**5";
static const lxl_str sl6553 = {.p = sl6553b, .cap = 0U, .len = 70U};
static char sl6554b[50] = " *      where   Q1  =  -1.6666666666666567384E-2,";
static const lxl_str sl6554 = {.p = sl6554b, .cap = 0U, .len = 49U};
static char sl6555b[50] = " *              Q2  =   3.9682539681370365873E-4,";
static const lxl_str sl6555 = {.p = sl6555b, .cap = 0U, .len = 49U};
static char sl6556b[50] = " *              Q3  =  -9.9206344733435987357E-6,";
static const lxl_str sl6556 = {.p = sl6556b, .cap = 0U, .len = 49U};
static char sl6557b[50] = " *              Q4  =   2.5051361420808517002E-7,";
static const lxl_str sl6557 = {.p = sl6557b, .cap = 0U, .len = 49U};
static char sl6558b[50] = " *              Q5  =  -6.2843505682382617102E-9;";
static const lxl_str sl6558 = {.p = sl6558b, .cap = 0U, .len = 49U};
static char sl6559b[28] = " *              z   =  r*r,";
static const lxl_str sl6559 = {.p = sl6559b, .cap = 0U, .len = 27U};
static char sl6560b[30] = " *      with error bounded by";
static const lxl_str sl6560 = {.p = sl6560b, .cap = 0U, .len = 29U};
static char sl6561b[53] = " *          |                  5           |     -61";
static const lxl_str sl6561 = {.p = sl6561b, .cap = 0U, .len = 52U};
static char sl6562b[50] = " *          | 1.0+Q1*z+...+Q5*z   -  R1(z) | <= 2";
static const lxl_str sl6562 = {.p = sl6562b, .cap = 0U, .len = 49U};
static char sl6563b[45] = " *          |                              |";
static const lxl_str sl6563 = {.p = sl6563b, .cap = 0U, .len = 44U};
static char sl6564b[62] = " *      expm1(r) = exp(r)-1 is then computed by the following";
static const lxl_str sl6564 = {.p = sl6564b, .cap = 0U, .len = 61U};
static char sl6565b[69] = " *      specific way which minimize the accumulation rounding error:";
static const lxl_str sl6565 = {.p = sl6565b, .cap = 0U, .len = 68U};
static char sl6566b[39] = " *                             2     3";
static const lxl_str sl6566 = {.p = sl6566b, .cap = 0U, .len = 38U};
static char sl6567b[64] = " *                            r     r    [ 3 - (R1 + R1*r/2)  ]";
static const lxl_str sl6567 = {.p = sl6567b, .cap = 0U, .len = 63U};
static char sl6568b[64] = " *            expm1(r) = r + --- + --- * [--------------------]";
static const lxl_str sl6568 = {.p = sl6568b, .cap = 0U, .len = 63U};
static char sl6569b[64] = " *                            2     2    [ 6 - r*(3 - R1*r/2) ]";
static const lxl_str sl6569 = {.p = sl6569b, .cap = 0U, .len = 63U};
static char sl6570b[66] = " *      To compensate the error in the argument reduction, we use";
static const lxl_str sl6570 = {.p = sl6570b, .cap = 0U, .len = 65U};
static char sl6571b[55] = " *              expm1(r+c) = expm1(r) + c + expm1(r)*c";
static const lxl_str sl6571 = {.p = sl6571b, .cap = 0U, .len = 54U};
static char sl6572b[48] = " *                         ~ expm1(r) + c + r*c";
static const lxl_str sl6572 = {.p = sl6572b, .cap = 0U, .len = 47U};
static char sl6573b[64] = " *      Thus c+r*c will be added in as the correction terms for";
static const lxl_str sl6573 = {.p = sl6573b, .cap = 0U, .len = 63U};
static char sl6574b[65] = " *      expm1(r+c). Now rearrange the term to avoid optimization";
static const lxl_str sl6574 = {.p = sl6574b, .cap = 0U, .len = 64U};
static char sl6575b[18] = " *      screw up:";
static const lxl_str sl6575 = {.p = sl6575b, .cap = 0U, .len = 17U};
static char sl6576b[72] = " *                      (      2                                    2 )";
static const lxl_str sl6576 = {.p = sl6576b, .cap = 0U, .len = 71U};
static char sl6577b[72] = " *                      ({  ( r    [ R1 -  (3 - R1*r/2) ]  )  }    r  )";
static const lxl_str sl6577 = {.p = sl6577b, .cap = 0U, .len = 71U};
static char sl6578b[72] = " *       expm1(r+c)~r - ({r*(--- * [--------------------]-c)-c} - --- )";
static const lxl_str sl6578 = {.p = sl6578b, .cap = 0U, .len = 71U};
static char sl6579b[72] = " *                      ({  ( 2    [ 6 - r*(3 - R1*r/2) ]  )  }    2  )";
static const lxl_str sl6579 = {.p = sl6579b, .cap = 0U, .len = 71U};
static char sl6580b[72] = " *                      (                                             )";
static const lxl_str sl6580 = {.p = sl6580b, .cap = 0U, .len = 71U};
static char sl6581b[27] = " *                 = r - E";
static const lxl_str sl6581 = {.p = sl6581b, .cap = 0U, .len = 26U};
static char sl6582b[39] = " *   3. Scale back to obtain expm1(x):";
static const lxl_str sl6582 = {.p = sl6582b, .cap = 0U, .len = 38U};
static char sl6583b[29] = " *      From step 1, we have";
static const lxl_str sl6583 = {.p = sl6583b, .cap = 0U, .len = 28U};
static char sl6584b[50] = " *         expm1(x) = either 2^k*[expm1(r)+1] - 1";
static const lxl_str sl6584 = {.p = sl6584b, .cap = 0U, .len = 49U};
static char sl6585b[55] = " *                  = or     2^k*[expm1(r) + (1-2^-k)]";
static const lxl_str sl6585 = {.p = sl6585b, .cap = 0U, .len = 54U};
static char sl6586b[30] = " *   4. Implementation notes:";
