static char sl6589b[65] = " *      (B). To achieve maximum accuracy, we compute expm1(x) by";
static const lxl_str sl6589 = {.p = sl6589b, .cap = 0U, .len = 64U};
static char sl6590b[71] = " *        (i)   if x < -56*ln2, return -1.0, (raise inexact if x!=inf)";
