static char sl6594b[60] = " *                     else          return  1.0+2.0*(r-E);";
static const lxl_str sl6594 = {.p = sl6594b, .cap = 0U, .len = 59U};
static char sl6595b[70] = " *        (v)   if (k<-2||k>56) return 2^k(1-(E-r)) - 1 (or exp(x)-1)";
static const lxl_str sl6595 = {.p = sl6595b, .cap = 0U, .len = 69U};
