static char sl6709b[26] = "/* double log1p(double x)";
static const lxl_str sl6709 = {.p = sl6709b, .cap = 0U, .len = 25U};
static char sl6710b[40] = " * Return the natural logarithm of 1+x.";
static const lxl_str sl6710 = {.p = sl6710b, .cap = 0U, .len = 39U};
static char sl6711b[12] = " * Method :";
static const lxl_str sl6711 = {.p = sl6711b, .cap = 0U, .len = 11U};
static char sl6712b[51] = " *   1. Argument Reduction: find k and f such that";
static const lxl_str sl6712 = {.p = sl6712b, .cap = 0U, .len = 50U};
static char sl6713b[43] = " *                      1+x = 2^k * (1+f),";
static const lxl_str sl6713 = {.p = sl6713b, .cap = 0U, .len = 42U};
static char sl6714b[46] = " *         where  sqrt(2)/2 < 1+f < sqrt(2) .";
static const lxl_str sl6714 = {.p = sl6714b, .cap = 0U, .len = 45U};
static char sl6715b[66] = " *      Note. If k=0, then f=x is exact. However, if k!=0, then f";
static const lxl_str sl6715 = {.p = sl6715b, .cap = 0U, .len = 65U};
static char sl6716b[69] = " *      may not be representable exactly. In that case, a correction";
static const lxl_str sl6716 = {.p = sl6716b, .cap = 0U, .len = 68U};
static char sl6717b[63] = " *      term is need. Let u=1+x rounded. Let c = (1+x)-u, then";
