static char sl6720b[61] = " *      (Note: when x > 2**53, one can simply return log(x))";
static const lxl_str sl6720 = {.p = sl6720b, .cap = 0U, .len = 60U};
static char sl6721b[45] = " *   2. Approximation of log(1+f): See log.c";
static const lxl_str sl6721 = {.p = sl6721b, .cap = 0U, .len = 44U};
static char sl6722b[62] = " *   3. Finally, log1p(x) = k*ln2 + log(1+f) + c/u. See log.c";
static const lxl_str sl6722 = {.p = sl6722b, .cap = 0U, .len = 61U};
static char sl6723b[65] = " *      log1p(x) is NaN with signal if x < -1 (including -INF) ;";
static const lxl_str sl6723 = {.p = sl6723b, .cap = 0U, .len = 64U};
static char sl6724b[60] = " *      log1p(+INF) is +INF; log1p(-1) is -INF with signal;";
static const lxl_str sl6724 = {.p = sl6724b, .cap = 0U, .len = 59U};
static char sl6725b[47] = " *      log1p(NaN) is that NaN with no signal.";
static const lxl_str sl6725 = {.p = sl6725b, .cap = 0U, .len = 46U};
static char sl6726b[62] = " * Note: Assuming log() return accurate answer, the following";
static const lxl_str sl6726 = {.p = sl6726b, .cap = 0U, .len = 61U};
static char sl6727b[72] = " *       algorithm can be used to compute log1p(x) to within a few ULP:";
static const lxl_str sl6727 = {.p = sl6727b, .cap = 0U, .len = 71U};
static char sl6728b[25] = " *              u = 1+x;";
static const lxl_str sl6728 = {.p = sl6728b, .cap = 0U, .len = 24U};
static char sl6729b[43] = " *              if(u==1.0) return x ; else";
static const lxl_str sl6729 = {.p = sl6729b, .cap = 0U, .len = 42U};
static char sl6730b[54] = " *                         return log(u)*(x/(u-1.0));";
static const lxl_str sl6730 = {.p = sl6730b, .cap = 0U, .len = 53U};
static char sl6731b[56] = " *       See HP-15C Advanced Functions Handbook, p.193.";
static const lxl_str sl6731 = {.p = sl6731b, .cap = 0U, .len = 55U};
static char sl6732b[62] = "ln2_hi = 6.93147180369123816490e-01,  /* 3fe62e42 fee00000 */";
static const lxl_str sl6732 = {.p = sl6732b, .cap = 0U, .len = 61U};
