static char sl6791b[55] = "/* ---- musl 1.2.5 src/math/__rem_pio2_large.c ---- */";
static const lxl_str sl6791 = {.p = sl6791b, .cap = 0U, .len = 54U};
static char sl6792b[57] = "/* origin: FreeBSD /usr/src/lib/msun/src/k_rem_pio2.c */";
static const lxl_str sl6792 = {.p = sl6792b, .cap = 0U, .len = 56U};
static char sl6793b[60] = " * Developed at SunSoft, a Sun Microsystems, Inc. business.";
static const lxl_str sl6793 = {.p = sl6793b, .cap = 0U, .len = 59U};
static char sl6794b[36] = " * __rem_pio2_large(x,y,e0,nx,prec)";
static const lxl_str sl6794 = {.p = sl6794b, .cap = 0U, .len = 35U};
static char sl6795b[35] = " * double x[],y[]; int e0,nx,prec;";
static const lxl_str sl6795 = {.p = sl6795b, .cap = 0U, .len = 34U};
static char sl6796b[59] = " * __rem_pio2_large return the last three digits of N with";
static const lxl_str sl6796 = {.p = sl6796b, .cap = 0U, .len = 58U};
static char sl6797b[31] = " *              y = x - N*pi/2";
static const lxl_str sl6797 = {.p = sl6797b, .cap = 0U, .len = 30U};
static char sl6798b[23] = " * so that |y| < pi/2.";
static const lxl_str sl6798 = {.p = sl6798b, .cap = 0U, .len = 22U};
static char sl6799b[70] = " * The method is to compute the integer (mod 8) and fraction parts of";
static const lxl_str sl6799 = {.p = sl6799b, .cap = 0U, .len = 69U};
static char sl6800b[65] = " * (2/pi)*x without doing the full multiplication. In general we";
static const lxl_str sl6800 = {.p = sl6800b, .cap = 0U, .len = 64U};
static char sl6801b[70] = " * skip the part of the product that are known to be a huge integer (";
static const lxl_str sl6801 = {.p = sl6801b, .cap = 0U, .len = 69U};
static char sl6802b[67] = " * more accurately, = 0 mod 8 ). Thus the number of operations are";
static const lxl_str sl6802 = {.p = sl6802b, .cap = 0U, .len = 66U};
static char sl6803b[45] = " * independent of the exponent of the input.";
static const lxl_str sl6803 = {.p = sl6803b, .cap = 0U, .len = 44U};
static char sl6804b[68] = " * (2/pi) is represented by an array of 24-bit integers in ipio2[].";
static const lxl_str sl6804 = {.p = sl6804b, .cap = 0U, .len = 67U};
static char sl6805b[21] = " * Input parameters:";
static const lxl_str sl6805 = {.p = sl6805b, .cap = 0U, .len = 20U};
static char sl6806b[69] = " *      x[]     The input value (must be positive) is broken into nx";
static const lxl_str sl6806 = {.p = sl6806b, .cap = 0U, .len = 68U};
static char sl6807b[70] = " *              pieces of 24-bit integers in double precision format.";
static const lxl_str sl6807 = {.p = sl6807b, .cap = 0U, .len = 69U};
static char sl6808b[71] = " *              x[i] will be the i-th 24 bit of x. The scaled exponent";
static const lxl_str sl6808 = {.p = sl6808b, .cap = 0U, .len = 70U};
static char sl6809b[72] = " *              of x[0] is given in input parameter e0 (i.e., x[0]*2^e0";
static const lxl_str sl6809 = {.p = sl6809b, .cap = 0U, .len = 71U};
static char sl6810b[41] = " *              match x's up to 24 bits.";
static const lxl_str sl6810 = {.p = sl6810b, .cap = 0U, .len = 40U};
static char sl6811b[77] = " *              Example of breaking a double positive z into x[0]+x[1]+x[2]:";
static const lxl_str sl6811 = {.p = sl6811b, .cap = 0U, .len = 76U};
static char sl6812b[41] = " *                      e0 = ilogb(z)-23";
static const lxl_str sl6812 = {.p = sl6812b, .cap = 0U, .len = 40U};
static char sl6813b[43] = " *                      z  = scalbn(z,-e0)";
static const lxl_str sl6813 = {.p = sl6813b, .cap = 0U, .len = 42U};
static char sl6814b[30] = " *              for i = 0,1,2";
static const lxl_str sl6814 = {.p = sl6814b, .cap = 0U, .len = 29U};
static char sl6815b[40] = " *                      x[i] = floor(z)";
static const lxl_str sl6815 = {.p = sl6815b, .cap = 0U, .len = 39U};
static char sl6816b[46] = " *                      z    = (z-x[i])*2**24";
static const lxl_str sl6816 = {.p = sl6816b, .cap = 0U, .len = 45U};
static char sl6817b[70] = " *      y[]     ouput result in an array of double precision numbers.";
static const lxl_str sl6817 = {.p = sl6817b, .cap = 0U, .len = 69U};
static char sl6818b[41] = " *              The dimension of y[] is:";
static const lxl_str sl6818 = {.p = sl6818b, .cap = 0U, .len = 40U};
static char sl6819b[50] = " *                      24-bit  precision       1";
static const lxl_str sl6819 = {.p = sl6819b, .cap = 0U, .len = 49U};
static char sl6820b[50] = " *                      53-bit  precision       2";
static const lxl_str sl6820 = {.p = sl6820b, .cap = 0U, .len = 49U};
static char sl6821b[50] = " *                      64-bit  precision       2";
static const lxl_str sl6821 = {.p = sl6821b, .cap = 0U, .len = 49U};
static char sl6822b[50] = " *                      113-bit precision       3";
static const lxl_str sl6822 = {.p = sl6822b, .cap = 0U, .len = 49U};
static char sl6823b[70] = " *              The actual value is the sum of them. Thus for 113-bit";
static const lxl_str sl6823 = {.p = sl6823b, .cap = 0U, .len = 69U};
static char sl6824b[61] = " *              precison, one may have to do something like:";
static const lxl_str sl6824 = {.p = sl6824b, .cap = 0U, .len = 60U};
static char sl6825b[48] = " *              long double t,w,r_head, r_tail;";
static const lxl_str sl6825 = {.p = sl6825b, .cap = 0U, .len = 47U};
static char sl6826b[59] = " *              t = (long double)y[2] + (long double)y[1];";
static const lxl_str sl6826 = {.p = sl6826b, .cap = 0U, .len = 58U};
static char sl6827b[39] = " *              w = (long double)y[0];";
static const lxl_str sl6827 = {.p = sl6827b, .cap = 0U, .len = 38U};
static char sl6828b[30] = " *              r_head = t+w;";
static const lxl_str sl6828 = {.p = sl6828b, .cap = 0U, .len = 29U};
static char sl6829b[43] = " *              r_tail = w - (r_head - t);";
static const lxl_str sl6829 = {.p = sl6829b, .cap = 0U, .len = 42U};
static char sl6830b[70] = " *      e0      The exponent of x[0]. Must be <= 16360 or you need to";
static const lxl_str sl6830 = {.p = sl6830b, .cap = 0U, .len = 69U};
static char sl6831b[40] = " *              expand the ipio2 table.";
static const lxl_str sl6831 = {.p = sl6831b, .cap = 0U, .len = 39U};
static char sl6832b[33] = " *      nx      dimension of x[]";
static const lxl_str sl6832 = {.p = sl6832b, .cap = 0U, .len = 32U};
static char sl6833b[53] = " *      prec    an integer indicating the precision:";
static const lxl_str sl6833 = {.p = sl6833b, .cap = 0U, .len = 52U};
static char sl6834b[50] = " *                      0       24  bits (single)";
static const lxl_str sl6834 = {.p = sl6834b, .cap = 0U, .len = 49U};
static char sl6835b[50] = " *                      1       53  bits (double)";
static const lxl_str sl6835 = {.p = sl6835b, .cap = 0U, .len = 49U};
static char sl6836b[52] = " *                      2       64  bits (extended)";
static const lxl_str sl6836 = {.p = sl6836b, .cap = 0U, .len = 51U};
static char sl6837b[48] = " *                      3       113 bits (quad)";
static const lxl_str sl6837 = {.p = sl6837b, .cap = 0U, .len = 47U};
static char sl6838b[22] = " * External function:";
static const lxl_str sl6838 = {.p = sl6838b, .cap = 0U, .len = 21U};
static char sl6839b[34] = " *      double scalbn(), floor();";
static const lxl_str sl6839 = {.p = sl6839b, .cap = 0U, .len = 33U};
static char sl6840b[52] = " * Here is the description of some local variables:";
static const lxl_str sl6840 = {.p = sl6840b, .cap = 0U, .len = 51U};
static char sl6841b[70] = " *      jk      jk+1 is the initial number of terms of ipio2[] needed";
static const lxl_str sl6841 = {.p = sl6841b, .cap = 0U, .len = 69U};
static char sl6842b[70] = " *              in the computation. The minimum and recommended value";
static const lxl_str sl6842 = {.p = sl6842b, .cap = 0U, .len = 69U};
static char sl6843b[74] = " *              for jk is 3,4,4,6 for single, double, extended, and quad.";
static const lxl_str sl6843 = {.p = sl6843b, .cap = 0U, .len = 73U};
static char sl6844b[72] = " *              jk+1 must be 2 larger than you might expect so that our";
static const lxl_str sl6844 = {.p = sl6844b, .cap = 0U, .len = 71U};
static char sl6845b[72] = " *              recomputation test works. (Up to 24 bits in the integer";
static const lxl_str sl6845 = {.p = sl6845b, .cap = 0U, .len = 71U};
static char sl6846b[72] = " *              part (the 24 bits of it that we compute) and 23 bits in";
static const lxl_str sl6846 = {.p = sl6846b, .cap = 0U, .len = 71U};
static char sl6847b[71] = " *              the fraction part may be lost to cancelation before we";
static const lxl_str sl6847 = {.p = sl6847b, .cap = 0U, .len = 70U};
static char sl6848b[28] = " *              recompute.)";
