static char sl6849b[64] = " *      jz      local integer variable indicating the number of";
static const lxl_str sl6849 = {.p = sl6849b, .cap = 0U, .len = 63U};
static char sl6850b[39] = " *              terms of ipio2[] used.";
static const lxl_str sl6850 = {.p = sl6850b, .cap = 0U, .len = 38U};
static char sl6851b[23] = " *      jx      nx - 1";
static const lxl_str sl6851 = {.p = sl6851b, .cap = 0U, .len = 22U};
static char sl6852b[67] = " *      jv      index for pointing to the suitable ipio2[] for the";
static const lxl_str sl6852 = {.p = sl6852b, .cap = 0U, .len = 66U};
static char sl6853b[49] = " *              computation. In general, we want";
static const lxl_str sl6853 = {.p = sl6853b, .cap = 0U, .len = 48U};
static char sl6854b[64] = " *                      ( 2^e0*x[0] * ipio2[jv-1]*2^(-24jv) )/8";
static const lxl_str sl6854 = {.p = sl6854b, .cap = 0U, .len = 63U};
static char sl6855b[36] = " *              is an integer. Thus";
static const lxl_str sl6855 = {.p = sl6855b, .cap = 0U, .len = 35U};
static char sl6856b[59] = " *                      e0-3-24*jv >= 0 or (e0-3)/24 >= jv";
static const lxl_str sl6856 = {.p = sl6856b, .cap = 0U, .len = 58U};
static char sl6857b[45] = " *              Hence jv = max(0,(e0-3)/24).";
static const lxl_str sl6857 = {.p = sl6857b, .cap = 0U, .len = 44U};
static char sl6858b[71] = " *      jp      jp+1 is the number of terms in PIo2[] needed, jp = jk.";
static const lxl_str sl6858 = {.p = sl6858b, .cap = 0U, .len = 70U};
static char sl6859b[67] = " *      q[]     double array with integral value, representing the";
